function createCounter() {
  let count = 0;          // private — unreachable from outside
  return {
    increment: () => ++count,
    value: () => count,
  };
}

const a = createCounter();
const b = createCounter();
a.increment();
a.increment();

console.log(a.value()); // 2
console.log(b.value()); // 0 — separate scope

const cart = {
  items: [10, 20],
  total() {
    // arrow inherits this from total()
    return this.items.reduce((sum, n) => sum + n, 0);
  },
};

console.log(cart.total()); // 30

