function getUser(id) {
  return fetch(`/api/users/${id}`).then((r) => {
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    return r.json();
  });
}

Promise.all([getUser(1), getUser(2)])
  .then(([a, b]) => console.log(a, b))
  .catch((err) => console.error("failed:", err.message));

